package org.sleepwell.app;
import java.time.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public final class RecordAchievementsTest {
 final long hour=3600000L,now=Instant.parse("2026-10-28T18:00:00Z").toEpochMilli();
 RecordEntry record(long id,String start,int hours){long s=Instant.parse(start).toEpochMilli();return new RecordEntry(id,s,s+hours*hour,hours*hour,"tracked","local","UTC",0,0,new RecordDraft(s,s+hours*hour),false,0,List.of(),"accelerometer","");}
 RecordEntry copy(RecordEntry r,String source,String origin,String zone,int interrupted,int changed,String sensor,Long active,List<RecordIntervals.Span> pauses){return new RecordEntry(r.id,r.rawStart,r.rawEnd,active,source,origin,zone,interrupted,changed,r.edit,r.edited,r.updated,pauses,sensor,"");}
 RecordAchievements.Evidence evidence(RecordEntry r){return new RecordAchievements.Evidence(r,List.of(new RecordIntervals.Span(r.rawStart,r.rawEnd)),true);}
 RecordAchievements calc(RecordEntry...rows){return new RecordAchievements(Arrays.stream(rows).map(this::evidence).toList(),now);}
 @Test public void emptyMissingDaysNeverBecomeAwards(){RecordAchievements a=calc();assertEquals(0,a.count);assertEquals(0,a.millis);assertFalse(a.reached(1));assertEquals(0,a.progress(30));}
 @Test public void thresholdsUseUniqueRecordedDaysAndBoundedProgress(){List<RecordAchievements.Evidence> rows=new ArrayList<>();for(int n=0;n<31;n++){long s=now-(n+2)*24*hour;RecordEntry r=new RecordEntry(n+1,s,s+4*hour,4*hour,"tracked","local","UTC",0,0,new RecordDraft(s,s+4*hour),false,0,List.of(),"accelerometer","");rows.add(evidence(r));}RecordAchievements a=new RecordAchievements(rows,now);assertEquals(31,a.count);assertEquals(30,a.progress(30));assertTrue(a.reached(1));assertTrue(a.reached(7));assertTrue(a.reached(30));assertEquals(124*hour,a.millis);}
 @Test public void pausesAwakeAndTrimsAreExcludedFromActualEvidence(){RecordEntry r=record(1,"2026-10-20T00:00:00Z",6);r=copy(r,"tracked","local","UTC",0,0,"accelerometer",5*hour,List.of(new RecordIntervals.Span(r.rawStart,r.rawStart+hour)));r.edit.start+=hour;r.edit.end-=hour;r.edit.awake.add(new RecordIntervals.Span(r.edit.start,r.edit.start+2*hour));assertEquals(0,calc(r).count);r.edit.awake.clear();assertEquals(1,calc(r).count);assertEquals(4*hour,calc(r).millis);}
 @Test public void unknownManualNapHealthInterruptedAndClockChangesDoNotQualify(){RecordEntry r=record(1,"2026-10-20T00:00:00Z",6);for(RecordEntry invalid:List.of(copy(r,"manual","local","UTC",0,0,"accelerometer",6*hour,List.of()),copy(r,"tracked","legacy","UTC",0,0,"accelerometer",6*hour,List.of()),copy(r,"tracked","local","UTC",1,0,"accelerometer",6*hour,List.of()),copy(r,"tracked","local","UTC",0,1,"accelerometer",6*hour,List.of()),copy(r,"tracked","local","",0,0,"accelerometer",6*hour,List.of()),copy(r,"tracked","local","UTC",0,0,"unspecified",6*hour,List.of()),copy(r,"tracked","local","UTC",0,0,"accelerometer",null,List.of())))assertEquals(0,calc(invalid).count);assertEquals(0,new RecordAchievements(List.of(new RecordAchievements.Evidence(r,evidence(r).measured,false)),now).count);r.edit.addTag("Nap");assertEquals(0,calc(r).count);}
 @Test public void samePhysicalIntervalAcrossZonesAndRestoredDuplicatesCountsOnce(){RecordEntry r=record(1,"2026-10-20T00:00:00Z",6);RecordEntry duplicate=new RecordEntry(2,r.rawStart,r.rawEnd,6*hour,"tracked","imported","Pacific/Honolulu",0,0,r.edit,false,0,List.of(),"accelerometer","");RecordAchievements a=calc(r,duplicate);assertEquals(1,a.count);assertEquals(6*hour,a.millis);assertEquals(LocalDate.of(2026,10,19),a.days.get(0).date);assertEquals(1,calc(duplicate).count);}
 @Test public void incompletePiecesOnOneRecordedDayCanReachThresholdWithoutDoubleCounting(){RecordEntry a=record(1,"2026-10-20T00:00:00Z",2),b=record(2,"2026-10-20T01:00:00Z",2);assertEquals(0,calc(a).count);RecordAchievements result=calc(a,b);assertEquals(1,result.count);assertEquals(3*hour,result.millis);}
 @Test public void dstDurationIsElapsedAndRecordedZoneDefinesDay(){RecordEntry r=record(1,"2026-10-25T00:00:00Z",4);r=copy(r,"tracked","local","Europe/London",0,0,"accelerometer",4*hour,List.of());assertEquals(4*hour,calc(r).millis);assertEquals(LocalDate.of(2026,10,24),calc(r).days.get(0).date);}
 @Test public void futureEmptyAndPartialValidCoverageDoNotQualify(){RecordEntry r=record(1,"2026-10-29T00:00:00Z",6);assertEquals(0,calc(r).count);r=record(1,"2026-10-20T00:00:00Z",6);assertEquals(0,new RecordAchievements(List.of(new RecordAchievements.Evidence(r,List.of(),true)),now).count);assertEquals(0,new RecordAchievements(List.of(new RecordAchievements.Evidence(r,List.of(new RecordIntervals.Span(r.rawStart,r.rawStart+2*hour)),true)),now).count);}
 @Test public void measuredEpochsRequireRealFiniteValuesSamplesAndSonarValidQuality(){RecordEntry motion=record(1,"2026-10-20T00:00:00Z",6),sonar=copy(motion,"tracked","local","UTC",0,0,"sonar_fmcw_v1",6*hour,List.of());long s=motion.rawStart;assertTrue(RecordAchievements.epoch(motion,s,s+60000,0d,10,null));assertFalse(RecordAchievements.epoch(motion,s,s+60000,null,10,null));assertFalse(RecordAchievements.epoch(motion,s,s+60000,Double.NaN,10,null));assertFalse(RecordAchievements.epoch(motion,s,s+60000,0d,0,null));assertFalse(RecordAchievements.epoch(motion,s,s+180000,0d,10,null));assertTrue(RecordAchievements.epoch(sonar,s,s+5000,0d,10,"VALID"));assertFalse(RecordAchievements.epoch(sonar,s,s+5000,null,10,"NO_ECHO"));assertFalse(RecordAchievements.epoch(sonar,s,s+5000,0d,10,"CALIBRATING"));assertFalse(RecordAchievements.epoch(sonar,s,s+6000,0d,10,"VALID"));assertFalse(RecordAchievements.epoch(sonar,s,s+5000,5d,10,"VALID"));}
}
